'use strict';
// Decisions retain their destination until the need is met or a danger interrupts it.
const behaviorOld={resident:planResident,selection:showSelection,onDuty:isOnDuty};
Object.assign(purposeNames,{herd:'Theo đàn',sleep:'Ngủ',rest:'Nghỉ ngơi',social:'Trò chuyện',play:'Chơi gần nhà',parent:'Theo người lớn',recover:'Nghỉ dưỡng thương'});
function hungryPredator(e){return laws.predators&&e.kind==='wolf'&&(e.hunger<58||mindFor(e).type==='hunt'&&e.hunger<90);}
function burningNear(e){let closest=null,best=Infinity;for(let y=Math.max(0,Math.floor(e.y)-2);y<Math.min(H,Math.floor(e.y)+3);y++)for(let x=Math.max(0,Math.floor(e.x)-2);x<Math.min(W,Math.floor(e.x)+3);x++)if(grid[idx(x,y)].fire>0){const d=Math.hypot(x+.5-e.x,y+.5-e.y);if(d<best){best=d;closest={x:x+.5,y:y+.5};}}return closest;}
safeDirection=function(e,threat){const angle=Math.atan2(e.y-threat.y,e.x-threat.x),choices=[];for(const distance of [5,3,1.5])for(let i=0;i<12;i++){const a=angle+(i%2?1:-1)*Math.ceil(i/2)*Math.PI/12,goal={x:e.x+Math.cos(a)*distance,y:e.y+Math.sin(a)*distance};if(!passFor(e,goal.x,goal.y)||!clearRoute(e,goal)||grid[idx(goal.x,goal.y)].fire>0)continue;choices.push({...goal,score:Math.hypot(goal.x-threat.x,goal.y-threat.y)-Math.abs(a-angle)*.4});}choices.sort((a,b)=>b.score-a.score);return choices[0]||null;};
function escapeDanger(e,danger){const m=mindFor(e);m.panicUntil=simTime+3;m.danger={x:danger.x,y:danger.y};if(m.type==='flee'&&m.goal&&Math.hypot(m.goal.x-danger.x,m.goal.y-danger.y)>Math.hypot(e.x-danger.x,e.y-danger.y)+1&&clearRoute(e,m.goal)){navigate(e);return;}go(e,safeDirection(e,danger),'flee',4);}
function pauseAnimal(e,type,seconds){stop(e,type);mindFor(e).until=simTime+seconds;motionFor(e).vx=motionFor(e).vy=0;}
function wanderAnimal(e,distance=4){const m=mindFor(e);if(m.goal&&simTime<m.until){navigate(e);return;}if(simTime<m.until)return;const angle=e.id*.91+simTime*.037;for(let k=0;k<8;k++){const a=angle+k*Math.PI/4,goal={x:e.x+Math.cos(a)*distance,y:e.y+Math.sin(a)*distance};if(passFor(e,goal.x,goal.y)&&clearRoute(e,goal)&&!grid[idx(goal.x,goal.y)].fire){go(e,goal,'wander',16);return;}}pauseAnimal(e,'rest',3);}
planAnimal=function(e){if(e.id===possessed)return;e.sailing=false;const m=mindFor(e),fire=laws.disasters?burningNear(e):null;if(fire){escapeDanger(e,fire);return;}const hour=readCalendar().hour;
if(e.kind==='sheep'){
const threats=around(e,7,p=>hungryPredator(p)&&(typeof suitablePrey!=='function'||suitablePrey(p,e))),wolf=threats.reduce((b,p)=>!b||Math.hypot(p.x-e.x,p.y-e.y)<Math.hypot(b.x-e.x,b.y-e.y)?p:b,null);if(wolf){escapeDanger(e,wolf);return;}if(m.type==='flee'&&m.panicUntil>simTime&&m.goal){navigate(e);return;}
if(e.hunger<62||m.type==='graze'&&e.hunger<88){if(grid[idx(e.x,e.y)].food>2){pauseAnimal(e,'graze',2);return;}if(m.type==='graze'&&m.goal&&grid[idx(m.goal.x,m.goal.y)].food>2){navigate(e);return;}if(m.foodRetry>simTime){wanderAnimal(e,2);return;}const food=nearestTile(e,t=>t.food>2&&!t.fire,9);if(food){go(e,food,'graze',16);return;}m.foodRetry=simTime+5;}
const flock=around(e,9,p=>p.kind==='sheep'&&(p.species||'sheep')===(e.species||'sheep')&&p.id<e.id).sort((a,b)=>a.id-b.id);if(flock.length){const leader=flock[0],distance=Math.hypot(leader.x-e.x,leader.y-e.y);if(distance>3.5){const a=e.id*2.4,goal={x:leader.x+Math.cos(a)*1.4,y:leader.y+Math.sin(a)*1.4};if(passFor(e,goal.x,goal.y)&&clearRoute(e,goal)){if(m.type==='herd'&&m.goal&&Math.hypot(m.goal.x-leader.x,m.goal.y-leader.y)<4){navigate(e);}else go(e,goal,'herd',14);return;}}}
if((hour>=21||hour<5)&&e.hunger>45){pauseAnimal(e,'sleep',4);return;}if(['rest','sleep','graze'].includes(m.type)&&simTime<m.until)return;if(m.type==='wander'&&!m.goal){pauseAnimal(e,'rest',3+e.id%5);return;}wanderAnimal(e,2.5);
}else if(e.kind==='wolf'){
const defenders=around(e,4,p=>p.kind==='human'&&(p.soldier||p.traits?.includes('strong')));if(e.hp<35&&defenders.length){escapeDanger(e,defenders[0]);return;}
if(laws.predators&&(e.hunger<58||m.type==='hunt'&&e.hunger<90)&&!(m.huntRest>simTime)){
let prey=entities.find(p=>p.id===m.prey&&p.hp>0&&Math.hypot(p.x-e.x,p.y-e.y)<16&&(p.kind==='sheep'||e.hunger<25&&p.kind==='human'));if(m.prey&&m.huntUntil<simTime){prey=null;m.prey=null;m.preyRetry=simTime+5;m.huntRest=simTime+4;}
if(!prey&&!(m.preyRetry>simTime)){const candidates=around(e,13,p=>(p.kind==='sheep'||e.hunger<25&&p.kind==='human'&&!p.soldier)&&(typeof suitablePrey!=='function'||suitablePrey(e,p)));candidates.sort((a,b)=>(a.kind==='human')-(b.kind==='human')||Math.hypot(a.x-e.x,a.y-e.y)-Math.hypot(b.x-e.x,b.y-e.y));prey=candidates.find(p=>clearRoute(e,p)||pathStep(e,p,false));if(prey){m.prey=prey.id;m.huntUntil=simTime+25;}else m.preyRetry=simTime+3;}
if(prey){if(Math.hypot(prey.x-e.x,prey.y-e.y)<1.2)stop(e,'hunt');else go(e,prey,'hunt',4);return;}}
m.prey=null;if(['sleep','rest'].includes(m.type)&&simTime<m.until)return;if(e.hunger>=75||m.huntRest>simTime){pauseAnimal(e,hour>=7&&hour<18?'sleep':'rest',4+e.id%5);return;}if(m.type==='wander'&&!m.goal){pauseAnimal(e,'rest',2);return;}wanderAnimal(e,5);
}};
function resolvePredation(e){if(!laws.predators||e.id===possessed)return;const m=mindFor(e);if(m.type!=='hunt'||simTime<(m.attackAt||0)||e.hunger>=90)return;const prey=entities.find(p=>p.id===m.prey&&p.hp>0);if(!prey||typeof suitablePrey==='function'&&!suitablePrey(e,prey)||Math.hypot(prey.x-e.x,prey.y-e.y)>=1.3)return;m.attackAt=simTime+1.2;damage(prey,18);if(prey.hp<=0){e.hunger=Math.min(100,e.hunger+55);m.prey=null;m.huntRest=simTime+8;pauseAnimal(e,'rest',8);}}
planResident=function(e){if(e.id===possessed)return;const m=mindFor(e),fire=laws.disasters?burningNear(e):null;if(fire){e.sailing=false;escapeDanger(e,fire);return;}const myKing=kingdomOf(e),danger=around(e,6,p=>hungryPredator(p)||p.kind==='human'&&wars.length&&atWar(myKing,kingdomOf(p)));if(danger.length){behaviorOld.resident(e);return;}
if(m.type==='flee'&&m.panicUntil>simTime&&m.goal){navigate(e);return;}
if(m.type==='food'&&e.hunger<78&&e.thirst>=35||m.type==='water'&&e.thirst<70&&e.hunger>=45){if(m.goal){navigate(e);return;}const village=villages.find(v=>v.id===e.village);if(village&&(m.type==='food'?village.food>0:village.water>0)){go(e,village,m.type,12);return;}}
if(e.hunger<45||e.thirst<35||e.soldier){behaviorOld.resident(e);return;}const home=houses.find(h=>h.village===e.village),v=villages.find(v=>v.id===e.village);
if(e.age<2){const parent=entities.find(p=>e.parents?.includes(p.id)&&p.hp>0&&p.kind==='human')||humans().find(p=>p.village===e.village&&p.age>=2&&p.hp>0&&!p.soldier),anchor=parent||home||v;if(['sleeping','resting'].includes(e.activity)){behaviorOld.resident(e);return;}if(anchor&&Math.hypot(e.x-anchor.x,e.y-anchor.y)>3){go(e,{x:anchor.x+.6*Math.cos(e.id),y:anchor.y+.6*Math.sin(e.id)},'parent',12);return;}if(m.type==='play'&&m.goal&&simTime<m.until){navigate(e);return;}if(m.until>simTime&&!m.goal)return;const a=e.id+simTime*.07,goal={x:(anchor?.x||e.x)+Math.cos(a)*1.8,y:(anchor?.y||e.y)+Math.sin(a)*1.8};if(passFor(e,goal.x,goal.y)&&clearRoute(e,goal))go(e,goal,'play',8);else{stop(e,'play');m.until=simTime+4;}return;}
if((e.hp<40||m.type==='recover'&&e.hp<75)&&home){if(Math.hypot(e.x-home.x,e.y-home.y)>1.2)go(e,home,'recover',20);else{stop(e,'recover');e.hp=Math.min(100,e.hp+.3);}return;}
if(['sleeping','resting'].includes(e.activity)||['storm','snow'].includes(weatherAt(e.x,e.y))){behaviorOld.resident(e);return;}
if(m.type==='social'&&simTime<m.socialUntil){if(m.goal)navigate(e);return;}m.nextSocial??=simTime+45+e.id%50;
if(simTime>=m.nextSocial&&!e.cargo&&e.energy>40&&e.hunger>65&&e.thirst>60){m.nextSocial=simTime+60+e.id%40;const peer=around(e,4,p=>p.kind==='human'&&p.village===e.village&&p.age>=2&&!p.soldier&&p.activity==='working')[0];if(peer){const goal={x:peer.x+Math.cos(e.id)*.9,y:peer.y+Math.sin(e.id)*.9};if(passFor(e,goal.x,goal.y)&&clearRoute(e,goal)){m.socialUntil=simTime+5;go(e,goal,'social',5);return;}}}
behaviorOld.resident(e);};
isOnDuty=e=>behaviorOld.onDuty(e)&&!['flee','food','water','social','play','parent','recover','shelter','home'].includes(mindFor(e).type);
function wantsMeal(e){return e.hunger<50||mindFor(e).type==='food'&&e.hunger<78;}
showSelection=function(id){behaviorOld.selection(id);const e=entities.find(e=>e.id===id);if(!e||e.kind==='human')return;const p=document.createElement('p');p.textContent='Tập tính: '+(purposeNames[mindFor(e).type]||'Nghỉ ngơi');$('selection').append(p);};
steerWorkers();
